// Получаем данные из предыдущих нод
const telegramData = $('Telegram Trigger').item.json;
const contextResult = $('Load Context from PostgreSQL').item.json;
const dealResult = $('Load Deal Stage').item.json;

// Текущее сообщение пользователя
const currentMessage = telegramData.message.text;

// Извлекаем историю диалога из БД
let messages = [];
let collectedData = { name: null, request: null, contact_method: null };


if (contextResult && contextResult.chat_id) {
  // Проверяем тип messages и парсим если нужно
  let rawMessages = contextResult.messages;
  if (typeof rawMessages === 'string') {
    try {
      messages = JSON.parse(rawMessages);
    } catch(e) {
      messages = [];
    }
  } else if (Array.isArray(rawMessages)) {
    messages = rawMessages;
  } else if (rawMessages && typeof rawMessages === 'object') {
    messages = Object.values(rawMessages);
  } else {
    messages = [];
  }

  // Аналогично для collected_data
  let rawCollectedData = contextResult.collected_data;
  if (typeof rawCollectedData === 'string') {
    try {
      collectedData = JSON.parse(rawCollectedData);
    } catch(e) {
      collectedData = { name: null, request: null, contact_method: null };
    }
  } else if (rawCollectedData && typeof rawCollectedData === 'object') {
    collectedData = rawCollectedData;
  }
}

let stage = 'new_lead';
let bitrixDealId = null;

if (dealResult && dealResult.stage) {
  stage = dealResult.stage || 'new_lead';
  bitrixDealId = dealResult.bitrix_deal_id || null;
}

// ФОРМИРУЕМ ПОЛНУЮ ИСТОРИЮ
let conversationHistory = '';
if (messages.length > 0) {
  conversationHistory = 'ИСТОРИЯ ДИАЛОГА:\n';
  // Показываем ВСЕ сообщения для полного контекста
  for (const msg of messages) {
    const role = msg.role === 'user' ? 'Клиент' : 'Ассистент';
    conversationHistory += `${role}: ${msg.content}\n`;
  }
  conversationHistory += '\n';
} else {
  conversationHistory = 'ИСТОРИЯ ДИАЛОГА: (новый диалог)\n\n';
}

// Формируем информацию о собранных данных
let collectedInfo = '';
if (collectedData.name || collectedData.request || collectedData.contact_method) {
  collectedInfo = 'УЖЕ СОБРАННЫЕ ДАННЫЕ:\n';
  if (collectedData.name) collectedInfo += `- Имя: ${collectedData.name}\n`;
  if (collectedData.request) collectedInfo += `- Запрос: ${collectedData.request}\n`;
  if (collectedData.contact_method) collectedInfo += `- Связь: ${collectedData.contact_method}\n`;
  collectedInfo += '\n';
}

// Формируем информацию о статусе
const statusInfo = `СТАТУС СДЕЛКИ:\n- Стадия: ${stage}\n- Bitrix24 ID: ${bitrixDealId || 'не создана'}\n\n`;

// ДЕБАГ: выводим загруженную историю
console.log('=== LOADED HISTORY ===');
console.log('Messages count:', messages.length);
console.log('Messages:', JSON.stringify(messages, null, 2));
console.log('Collected data:', JSON.stringify(collectedData, null, 2));
console.log('Stage:', stage);
console.log('Bitrix Deal ID:', bitrixDealId);

// Возвращаем данные
return {
  conversation_history: conversationHistory,
  collected_data_info: collectedInfo,
  status_info: statusInfo,
  current_message: currentMessage,
  chat_id: telegramData.message.chat.id,
  user_name: telegramData.message.chat.first_name || 'Клиент',
  // ВАЖНО: передаем полную историю для сохранения
  full_messages_history: messages,
  full_collected_data: collectedData
};

// Получаем ответ от AI Agent
const aiResponse = $input.first().json;
const telegramData = $('Telegram Trigger').item.json;
const previousContext = $('Code in JavaScript').item.json;

// Парсим JSON ответ от AI
let parsedResponse = {};
let assistantReply = "";
let newData = { name: null, request: null, contact_method: null };

try {
  let responseText = aiResponse.output || aiResponse.text || JSON.stringify(aiResponse);
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    parsedResponse = JSON.parse(jsonMatch[0]);
    assistantReply = parsedResponse.reply || responseText;

    const cleanValue = (val) => {
      if (val === null || val === undefined) return null;
      if (Array.isArray(val) && val.length === 1 && val[0] === null) return null;
      if (Array.isArray(val) && val.length > 0) return val[0];
      if (val === "[null]" || val === "null") return null;
      return val;
    };

    newData = {
      name: cleanValue(parsedResponse.name),
      request: cleanValue(parsedResponse.request),
      contact_method: cleanValue(parsedResponse.contact_method)
    };
  } else {
    assistantReply = responseText;
  }
} catch (e) {
  console.error("Parse error:", e);
  assistantReply = "Продолжайте, пожалуйста.";
}

// Загружаем старые данные из контекста
const oldData = previousContext.full_collected_data || { name: null, request: null, contact_method: null };

// Обновляем собранные данные
const updatedCollectedData = {
  name: (newData.name !== null && newData.name !== undefined) ? newData.name : oldData.name,
  request: (newData.request !== null && newData.request !== undefined) ? newData.request : oldData.request,
  contact_method: (newData.contact_method !== null && newData.contact_method !== undefined) ? newData.contact_method : oldData.contact_method
};

// Подсчитываем заполненные поля
const filledCount = Object.values(updatedCollectedData).filter(v => v && v !== null && v !== "" && v !== "[null]").length;

// Определяем стадию
let newStage = 'new_lead';
if (filledCount === 0) newStage = 'new_lead';
else if (filledCount < 3) newStage = 'in_work';
else newStage = 'qualified';

const newMessages = [
  {
    role: "user",
    content: previousContext.current_message
  },
  {
    role: "assistant",
    content: assistantReply
  }
];

console.log('=== NEW MESSAGES ===');
console.log('New messages count:', newMessages.length);
console.log('New messages:', JSON.stringify(newMessages, null, 2));

return {
  chat_id: Number(telegramData.message.chat.id),
  new_messages: newMessages,
  collected_data: updatedCollectedData,
  stage: newStage,
  all_fields_collected: filledCount === 3,
  assistant_reply: assistantReply
};
